});
/**
 * Diff type for tracking Attributes changes.
 * [👤semio📚js💻semio🔖attribute🛠️attributesdiff](repo://p/u/semio/b/l/js/f/semio.ts/s/Attribute/d/i/AttributesDiff)
 **/
