  if (appliedDiff.removed) inverse.added = original.filter((i) => removedGuids.includes(i.guid));
  if (appliedDiff.added) inverse.removed = appliedDiff.added.map((i) => ({ guid: i.guid }));
  if (appliedDiff.updated) {
