          gltf: "model/gltf+json",
          "3dm": "model/vnd.3dm",
          png: "image/png",
          jpg: "image/jpeg",
          jpeg: "image/jpeg",
          svg: "image/svg+xml",
          pdf: "application/pdf",
          zip: "application/zip",
          json: "application/json",
