          connection.connecting.piece.guid,
          connection.connecting.designPiece?.guid || null,
          connection.connecting.connector.guid,
          connection.gap || 0,
          connection.shift || 0,
          connection.rise || 0,
          connection.rotation || 0,
          connection.turn || 0,
