    store.apply({ name: "Updated" });
    expect(store.getSnapshot().kit.name).toBe("Updated");
    expect(store.getSnapshot().sync.dirty).toBe(true);
    expect(notified).toBe(1);
  });

  it("replace swaps the entire kit", async () => {
