 * [👤semio📚js💻semio🔖utilities🪨normalize](repo://p/u/semio/b/l/js/f/semio.ts/s/Utilities/d/i/normalize)
 **/
export const normalize = (val: string | undefined | null): string => (val === undefined || val === null ? "" : val);
