      if (!originalPiece) return null;

      const pieceDiff: PieceDiff = {};

      if (flatPiece.plane && JSON.stringify(flatPiece.plane) !== JSON.stringify(originalPiece.plane)) {
        pieceDiff.plane = flatPiece.plane;
