  const zipEntries = new Map<string, any>();
  for (const [path, zipEntry] of Object.entries(zip.files)) {
    if (!(zipEntry as any).dir && !path.startsWith(".semio/") && path !== "kit.json") {
      zipEntries.set(path, zipEntry);
