      x: acc.x + plane.origin.x / planes.length,
      y: acc.y + plane.origin.y / planes.length,
      z: acc.z + plane.origin.z / planes.length,
    }),
    { x: 0, y: 0, z: 0 },
  );

  const baseXAxis = planes[0].xAxis;
  const baseYAxis = planes[0].yAxis;

