// XState state machine definition for the sketchpad application lifecycle.

/**
 * XState machine governing sketchpad navigation, kit management, and app state transitions.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🪨sketchpadmachine](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/d/i/sketchpadMachine)
 **/
export const sketchpadMachine = setup({
  types: {
    context: {} as SketchpadContext,
    events: {} as SketchpadEvent,
    input: {} as SketchpadMachineInput,
  },
  guards: {
    canNavigateBack: ({ context }) => {
      return context.sketchpad.navigationHistoryIndex > 0;
    },
    canNavigateForward: ({ context }) => {
      return context.sketchpad.navigationHistoryIndex < context.sketchpad.navigationHistory.length - 1;
    },

    hasHomeHover: ({ context }) => {
