    const currentPanel = context.kitApp.fullscreenWindow;
    const newPanel = currentPanel === KitAppFullscreenWindow.Table ? KitAppFullscreenWindow.None : KitAppFullscreenWindow.Table;
    return {
      diff: {
        fullscreenWindow: newPanel,
