// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨getfileicon](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/getFileIcon)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨getfileicon](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/getFileIcon)
 * getFileIcon holds the data fields for a getFileIcon record.
 **/
const getFileIcon = (fileName: string) => {
  if (!fileName) return <DocumentIcon className="size-tiny" />;
  const extension = fileName.split(".").pop()?.toLowerCase();
  switch (extension) {
    case "jpg":
    case "jpeg":
    case "png":
    case "gif":
    case "svg":
    case "webp":
    case "bmp":
      return <FileImageIcon className="size-tiny" />;
    case "mp4":
    case "avi":
    case "mov":
    case "mkv":
    case "webm":
      return <FileVideoIcon className="size-tiny" />;
    case "json":
      return <FileJsonIcon className="size-tiny" />;
    case "js":
    case "ts":
    case "jsx":
    case "tsx":
    case "py":
    case "java":
    case "cpp":
    case "c":
    case "h":
    case "cs":
    case "rb":
    case "go":
    case "rs":
    case "php":
    case "html":
    case "css":
    case "scss":
    case "xml":
      return <FileCodeIcon className="size-tiny" />;
    case "csv":
    case "xlsx":
    case "xls":
      return <FileSpreadsheetIcon className="size-tiny" />;
    case "txt":
    case "md":
    case "pdf":
    case "doc":
    case "docx":
      return <FileTypeIcon className="size-tiny" />;
    default:
      return <DocumentIcon className="size-tiny" />;
  }
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨getrowicon](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/getRowIcon)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨getrowicon](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/getRowIcon)
 * getRowIcon holds the data fields for a getRowIcon record.
 **/
const getRowIcon = (row: TableRow): string | React.ReactNode | undefined => {
  switch (row.kind) {
    case "designs":
      return (row.data as Design).icon;
    case "types":
      return (row.data as Type).icon;
    case "qualities":
      return (row.data as Quality).icon;
    case "files":
      return getFileIcon((row.data as SemioFile).name);
    case "folders":
      return <FolderIcon className="size-tiny" />;
    case "authors":
      return <UserIcon className="size-tiny" />;
    default:
      return undefined;
  }
};

