 * [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖table🛠️usekitappyjstoxstatesync](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/useKitAppYjsToXStateSync)
 **/
class ErrorBoundary extends React.Component<{ children: React.ReactNode; fallback: React.ReactNode }, { hasError: boolean; error: Error | null }> {
  constructor(props: { children: React.ReactNode; fallback: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) { }

  componentDidUpdate(prevProps: { children: React.ReactNode; fallback: React.ReactNode }) {
    if (prevProps.children !== this.props.children && this.state.hasError) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback;
    }
    return this.props.children;
  }
}

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🛠️usekitappyjstoxstatesync](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/useKitAppYjsToXStateSync)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨usekitappyjstoxstatesync](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/useKitAppYjsToXStateSync)
 * useKitAppYjsToXStateSync holds the data fields for a useKitAppYjsToXStateSync record.
 **/
function useKitAppYjsToXStateSync() {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const kitGuid = kitScope?.guid ?? "";
  const sketchpadStore = useSketchpadStore();
  const sketchpadCommands = useSketchpadCommands();
  const hasKit = useHasKit(kitGuid);
  const initializedKeyRef = useRef<string | null>(null);
  const syncedKeyRef = useRef<string | null>(null);

  useLayoutEffect(() => {
    if (!kitGuid || !hasKit) return;

    if (!sketchpadStore.hasKitApp({ kit: kitGuid })) {
      sketchpadCommands.createKitApp("semio.sketchpad.app.kit.autoCreateForSync", { kit: kitGuid });
    }
  }, [kitGuid, hasKit, sketchpadStore, sketchpadCommands]);

  useLayoutEffect(() => {
    if (!kitGuid || !hasKit) return;
    const initKey = kitGuid;
    if (initializedKeyRef.current === initKey) return;

    let xstateInitialState;
    if (sketchpadStore.hasKitApp({ kit: kitGuid })) {
      const store = sketchpadStore.kitApp(kitGuid);
      const initialState = store.snapshot();

      xstateInitialState = {
        ...createDefaultKitAppState(),
        ...initialState,
        activeTool: initialState.activeTool ?? ToolKind.SELECTION_NORMAL,
        expandedRows: new Set(initialState.expandedRows || []),
        transaction: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      };
    } else {
      xstateInitialState = {
        ...createDefaultKitAppState(),
        panelVisibility: defaultPanelVisibility,
        activeTool: ToolKind.SELECTION_NORMAL,
        expandedRows: new Set(),
        transaction: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      };
    }

    actor.send({
      type: "KIT.INIT",
      kitGuid,
      state: xstateInitialState,
    });
    initializedKeyRef.current = initKey;
  }, [actor, sketchpadStore, kitGuid, hasKit]);

  useEffect(() => {
    if (!kitGuid || !hasKit || initializedKeyRef.current !== kitGuid) return;
    if (syncedKeyRef.current === kitGuid) return;
    if (!sketchpadStore.hasKitApp({ kit: kitGuid })) return;

    const store = sketchpadStore.kitApp(kitGuid);
    const currentState = store.snapshot();

    const xstateState = {
      ...currentState,
      expandedRows: new Set(currentState.expandedRows || []),
    };

    actor.send({
      type: "KIT.SYNC",
      kitGuid,
      state: xstateState,
    });
    syncedKeyRef.current = kitGuid;
  }, [actor, sketchpadStore, kitGuid, hasKit]);
}

