/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingedge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingEdge)
 **/
const FloatingEdge: FC<EdgeProps> = ({ id, source, target, markerEnd, style, selected, data }) => {
  const sourceNode = useInternalNode(source);
  const targetNode = useInternalNode(target);
  const debugLogRef = useRef(0);

  if (!sourceNode || !targetNode) {
    return null;
  }

  const { sx, sy, tx, ty, sourcePos: sPos, targetPos: tPos } = resolveDiagramEdgeAnchors(sourceNode, targetNode);

  const [edgePath] = getBezierPath({
    sourceX: sx,
    sourceY: sy,
    sourcePosition: sPos,
    targetX: tx,
    targetY: ty,
    targetPosition: tPos,
  });

  const relationship = data?.relationship as "part-of" | "reference";
  let stroke = relationship === "part-of" ? "var(--accent-secondary)" : "var(--foreground)";
  let strokeWidth = relationship === "reference" ? 1 : 3;
  let dasharray = relationship === "reference" ? "5 5" : undefined;
  let opacity = 1;

  if (selected) {
    stroke = "var(--active-base)";
    strokeWidth = Math.max(strokeWidth, 3);
    dasharray = undefined;
    opacity = 1;
  }

  return (
    <g>
      <BaseEdge
        id={id}
        path={edgePath}
        style={{
          ...style,
          stroke,
          strokeWidth,
          strokeDasharray: dasharray,
          opacity,
        }}
        className="transition-colors duration-200"
      />
      {KIT_DIAGRAM_DEBUG ? <circle cx={sx} cy={sy} r={3} fill="var(--accent-secondary)" stroke="none" pointerEvents="none" /> : null}
      {KIT_DIAGRAM_DEBUG ? <circle cx={tx} cy={ty} r={3} fill="var(--foreground)" stroke="none" pointerEvents="none" /> : null}
    </g>
  );
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingconnectionline](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingConnectionLine)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingconnectionline](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingConnectionLine)
 * FloatingConnectionLine holds the data fields for a FloatingConnectionLine record.
 **/
const FloatingConnectionLine: FC<ConnectionLineComponentProps> = ({ fromX, fromY, toX, toY, fromNode, toNode, pointer }) => {
  const { getNodes } = useReactFlow();
  const fromKind = resolveDiagramNodeKind(fromNode);
  const fromPosition = resolveDiagramNodePosition(fromNode);
  const fromFrame = resolveDiagramNodeFrame(fromNode, fromKind);
  const targetPoint = pointer ?? { x: toX, y: toY };
  const sourceDirection = kitDiagramVector(kitDiagramToAbsolutePoint(fromPosition, { x: fromFrame.width / 2, y: fromFrame.height / 2 }), targetPoint);
  const sourceAnchor = getKitDiagramShapeStrategy(fromKind).resolveNearestPoint(sourceDirection, fromFrame);
  let sourceX = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).x;
  let sourceY = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).y;
  let sourcePosition = toReactFlowPosition(sourceAnchor.side);
  let targetX = toX;
  let targetY = toY;
  let targetPosition = toNode ? Position.Top : toY >= fromY ? Position.Bottom : Position.Top;

  if (toNode) {
    const resolved = resolveDiagramEdgeAnchors(fromNode, toNode);
    sourceX = resolved.sx;
    sourceY = resolved.sy;
    sourcePosition = resolved.sourcePos;
    targetX = resolved.tx;
    targetY = resolved.ty;
    targetPosition = resolved.targetPos;
  } else {
    const proximity = getNodes()
      .filter((node) => node.id !== fromNode.id)
      .map((node) => {
        const kind = resolveDiagramNodeKind(node);
        const position = resolveDiagramNodePosition(node);
        const frame = resolveDiagramNodeFrame(node, kind);
        return resolveKitDiagramProximityAnchor(node.id, { kind, position, frame }, targetPoint);
      })
      .sort((a, b) => a.distance - b.distance)[0];

    if (proximity && proximity.distance <= KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE) {
      targetX = proximity.anchor.absolutePoint.x;
      targetY = proximity.anchor.absolutePoint.y;
      targetPosition = toReactFlowPosition(proximity.anchor.localPoint.side);
    } else {
      targetPosition = toReactFlowPosition(kitDiagramInferSnapSide({ x: toX - fromPosition.x, y: toY - fromPosition.y }, fromFrame, fromFrame));
    }
  }
  const edgePath = getBezierPath({
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  })[0];

  return <BaseEdge path={edgePath} style={{ stroke: "var(--active-base)", strokeWidth: 3 }} />;
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨buildkitdiagramdata](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/buildKitDiagramData)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨buildkitdiagramdata](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/buildKitDiagramData)
 * buildKitDiagramData holds the data fields for a buildKitDiagramData record.
 **/
const buildKitDiagramData = (kit: Kit): { nodes: Node<KitDiagramNode>[]; edges: Edge[] } => {
  const nodes: Node<KitDiagramNode>[] = [];
  const edges: Edge[] = [];

  const kindGroups: KitDiagramNodeKind[] = ["type", "design", "quality", "port", "tag", "concept", "file", "folder", "author"];

  for (const kind of kindGroups) {
    let items: Array<{ guid: string; name: string; icon?: any; parentGuid?: string; concepts?: string[] }> = [];

    switch (kind) {
      case "type":
        items = (kit.types ?? []).filter(Boolean).map((t) => ({
          guid: t.guid,
          name: t.name,
          icon: t.icon,
          parentGuid: t.parent?.guid,
          concepts: (t.concepts ?? []).map((c: any) => (typeof c === "string" ? c : c?.guid)).filter((guid): guid is string => Boolean(guid)),
        }));
        break;
      case "design":
        items = (kit.designs ?? []).filter(Boolean).map((d) => ({
          guid: d.guid,
          name: d.name,
          icon: d.icon,
          parentGuid: d.parent?.guid,
          concepts: (d.concepts ?? []).map((c: any) => (typeof c === "string" ? c : c?.guid)).filter((guid): guid is string => Boolean(guid)),
        }));
        break;
      case "quality":
        items = (kit.qualities ?? []).filter(Boolean).map((q) => ({ guid: q.guid, name: q.name, icon: q.icon }));
        break;
      case "port":
        items = (kit.ports ?? []).filter(Boolean).map((i) => ({ guid: i.guid, name: i.name, icon: i.icon }));
        break;
      case "tag":
        items = (kit.tags ?? []).filter(Boolean).map((t) => ({ guid: t.guid, name: t.name, icon: t.icon }));
        break;
      case "concept":
        items = (kit.concepts ?? []).filter(Boolean).map((c) => ({ guid: c.guid, name: c.name, icon: c.icon }));
        break;
      case "file":
        items = (kit.files ?? []).filter(Boolean).map((f) => ({ guid: f.guid, name: f.name, icon: getFileIcon(f.name), parentGuid: f.folder?.guid }));
        break;
      case "folder":
        items = (kit.folders ?? []).filter(Boolean).map((f) => ({ guid: f.guid, name: f.name, icon: <FolderIcon className="size-tiny" />, parentGuid: f.parent?.guid }));
        break;
      case "author":
        items = (kit.authors ?? []).filter(Boolean).map((a) => ({ guid: a.guid, name: a.name, icon: <UserIcon className="size-tiny" /> }));
        break;
    }

    for (const item of items) {
      const nodeId = `${kind}:${item.guid}`;
      const frame = getKitDiagramNodeFrameForKind(kind);
      nodes.push({
        id: nodeId,
        type: "artifact",
        position: { x: 0, y: 0 },
        width: frame.width,
        height: frame.height,
        data: {
          guid: item.guid,
          name: item.name,
          kind,
          icon: item.icon,
          parentGuid: item.parentGuid,
          concepts: item.concepts,
        },
      });

      if (item.parentGuid) {
        let parentKind = kind;
        if (kind === "file") parentKind = "folder";
        edges.push({
          id: `${kind}-${item.parentGuid}-${item.guid}`,
          source: `${parentKind}:${item.parentGuid}`,
          target: nodeId,
          type: "floating",
          style: edgeStyle["part-of"],
          data: { relationship: "part-of" },
        });
      }
    }
  }

  for (const design of kit.designs ?? []) {
    for (const piece of design.pieces ?? []) {
      if (piece.type?.guid) {
        const typeGuid = piece.type.guid;
        const sourceId = `type:${typeGuid}`;
        const targetId = `design:${design.guid}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
      if (piece.design?.guid) {
        const nestedDesignGuid = piece.design.guid;
        const sourceId = `design:${nestedDesignGuid}`;
        const targetId = `design:${design.guid}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
    }
  }

  return { nodes, edges };
};

const hasAnySelection = (selection: KitAppSelection): boolean =>
  (selection.types?.length ?? 0) > 0 ||
  (selection.designs?.length ?? 0) > 0 ||
  (selection.qualities?.length ?? 0) > 0 ||
  (selection.ports?.length ?? 0) > 0 ||
  (selection.tags?.length ?? 0) > 0 ||
  (selection.concepts?.length ?? 0) > 0 ||
  (selection.files?.length ?? 0) > 0 ||
  (selection.folders?.length ?? 0) > 0 ||
  (selection.authors?.length ?? 0) > 0;

const buildSelectionKit = (kit: Kit, selection: KitAppSelection): Kit => {
  const selectedTypeGuids = new Set(selection.types ?? []);
  const selectedDesignGuids = new Set(selection.designs ?? []);
  const selectedPortGuids = new Set(selection.ports ?? []);
  const selectedTagGuids = new Set(selection.tags ?? []);
  const selectedConceptGuids = new Set(selection.concepts ?? []);
  const selectedFileIds = new Set(selection.files ?? []);
  const selectedFolderGuids = new Set(selection.folders ?? []);
  const selectedAuthorIds = new Set(selection.authors ?? []);
  const selectedQualityIds = new Set(selection.qualities ?? []);
  const typeByGuid = new Map((kit.types ?? []).map((t) => [t.guid, t]));
  const collectAncestorTypes = (guid: string, collected: Set<string>) => {
    if (collected.has(guid)) return;
    collected.add(guid);
    const t = typeByGuid.get(guid);
    if (t?.parent?.guid) collectAncestorTypes(t.parent.guid, collected);
  };
  const allTypeGuids = new Set(selectedTypeGuids);
  for (const guid of selectedTypeGuids) collectAncestorTypes(guid, allTypeGuids);
  const designByGuid = new Map((kit.designs ?? []).map((d) => [d.guid, d]));
  const collectAncestorDesigns = (guid: string, collected: Set<string>) => {
    if (collected.has(guid)) return;
    collected.add(guid);
    const d = designByGuid.get(guid);
    if (d?.parent?.guid) collectAncestorDesigns(d.parent.guid, collected);
  };
  const allDesignGuids = new Set(selectedDesignGuids);
  for (const guid of selectedDesignGuids) collectAncestorDesigns(guid, allDesignGuids);
  for (const designGuid of allDesignGuids) {
    const d = designByGuid.get(designGuid);
    for (const piece of d?.pieces ?? []) {
      if (piece.type?.guid && typeByGuid.has(piece.type.guid)) collectAncestorTypes(piece.type.guid, allTypeGuids);
    }
  }
  for (const typeGuid of allTypeGuids) {
    const t = typeByGuid.get(typeGuid);
    for (const connector of t?.connectors ?? []) {
      if (connector.port?.guid) selectedPortGuids.add(connector.port.guid);
    }
  }
  const types = (kit.types ?? []).filter((t) => allTypeGuids.has(t.guid));
  const designs = (kit.designs ?? []).filter((d) => allDesignGuids.has(d.guid));
  const ports = (kit.ports ?? []).filter((p) => selectedPortGuids.has(p.guid));
  const tags = (kit.tags ?? []).filter((t) => selectedTagGuids.has(t.guid));
  const concepts = (kit.concepts ?? []).filter((c) => selectedConceptGuids.has(c.guid));
  const files = (kit.files ?? []).filter((f) => selectedFileIds.has(f.guid));
  const folders = (kit.folders ?? []).filter((f) => selectedFolderGuids.has(f.guid));
  const authors = (kit.authors ?? []).filter((a) => selectedAuthorIds.has(a.guid));
  const qualities = (kit.qualities ?? []).filter((q) => selectedQualityIds.has(q.guid));
  return {
    ...kit,
    types,
    designs,
    ports,
    tags,
    concepts,
    files,
    folders,
    authors,
    qualities,
  };
};

