      }
      return;
    }
    const nodesSnapshot = diagramNodesRef.current;
    const edgesSnapshot = diagramEdgesRef.current;
    const nodesCopy: ForceNode[] = nodesSnapshot.map((node) => ({
      id: node.id,
      x: node.position.x,
      y: node.position.y,
      data: node.data,
    }));
    const linksCopy: ForceLink[] = edgesSnapshot.map((edge) => ({
      id: edge.id,
      source: edge.source,
