/**
 * Central store managing Sync-backed sketchpad state with reactive subscriptions.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️sketchpadstore](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/SketchpadStore)
 **/
export class SketchpadStore {
  private static _modulesLoaded = false;
  public static _loadModules() {
    if (SketchpadStore._modulesLoaded) return;
    SketchpadStore._modulesLoaded = true;
    // All modules are now consolidated in this file, no dynamic imports needed
  }
  private readonly id: string | undefined;
  private readonly remote: RemoteProviders | undefined;
  private readonly syncDoc: SyncDoc;
  private readonly syncSketchpad: SyncSketchpad;
  private readonly kits: Map<string, KitStore>;
  private readonly syncKits: SyncKitMetadatas;
  private homeStore?: HomeStoreInstance;
  private readonly syncKitApps: SyncKitApps;
  private readonly kitApps: Map<string, KitAppStoreInstance>;
  private readonly typeApps: Map<string, TypeAppStoreInstance>;
  private readonly qualityApps: Map<string, QualityAppStoreInstance>;
  private readonly designApps: Map<string, Map<string, DesignAppStoreInstance>>;
  private readonly persistence?: PersistenceProvider;
  private readonly persistenceFactory?: PersistenceFactory;
  private readonly commandRegistry: Map<string, (context: SketchpadCommandContext, ...rest: any[]) => SketchpadCommandResult>;
  private readonly commandMetadata: Map<string, { user?: boolean }>;
  private cache?: SketchpadState;
  private cacheHash?: string;
  private kitShallowsCache?: KitShallow[];
  private kitShallowsVersion: number = 0;
  private kitShallowsCacheVersion: number = -1;
  private readonly kitCreatedSubscribers: Set<() => void>;
  private readonly kitDeletedSubscribers: Set<() => void>;
  private readonly kitAppCreatedSubscribers: Set<() => void>;
  private readonly kitAppDeletedSubscribers: Set<() => void>;
  private readonly typeAppCreatedSubscribers: Set<() => void>;
  private readonly typeAppDeletedSubscribers: Set<() => void>;
  private readonly qualityAppCreatedSubscribers: Set<() => void>;
  private readonly qualityAppDeletedSubscribers: Set<() => void>;
  private readonly designAppCreatedSubscribers: Set<() => void>;
  private readonly designAppDeletedSubscribers: Set<() => void>;
  private readonly tutorialStoreInstance: any;
  private readonly injectedKitStore?: KitStore;
  private readonly temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly folderKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly fileKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly remoteKitStoreFactory?: SketchpadKitStoreFactory;
  actor?: SketchpadActorRef;
  private actorUnsubscribe?: () => void;

  constructor(
    id?: string,
    remote?: RemoteProviders,
    initialState?: ExtendedInitialState,
    persistenceFactory?: PersistenceFactory,
    injectedKitStore?: KitStore,
    temporaryKitStoreFactory?: SketchpadKitStoreFactory,
    folderKitStoreFactory?: SketchpadKitStoreFactory,
    fileKitStoreFactory?: SketchpadKitStoreFactory,
    remoteKitStoreFactory?: SketchpadKitStoreFactory,
  ) {
    this.id = id;
    this.remote = remote;
    this.persistenceFactory = persistenceFactory;
    this.injectedKitStore = injectedKitStore;
    this.temporaryKitStoreFactory = temporaryKitStoreFactory;
    this.folderKitStoreFactory = folderKitStoreFactory;
    this.fileKitStoreFactory = fileKitStoreFactory;
    this.remoteKitStoreFactory = remoteKitStoreFactory;
    this.syncDoc = createSyncDocFactory()();
    this.kits = new Map();
    this.kitApps = new Map();
    this.typeApps = new Map();
    this.qualityApps = new Map();
    this.designApps = new Map();
    this.commandRegistry = new Map();
    this.commandMetadata = new Map();
    this.kitCreatedSubscribers = new Set();
    this.kitDeletedSubscribers = new Set();
    this.kitAppCreatedSubscribers = new Set();
    this.kitAppDeletedSubscribers = new Set();
    this.typeAppCreatedSubscribers = new Set();
    this.typeAppDeletedSubscribers = new Set();
    this.qualityAppCreatedSubscribers = new Set();
    this.qualityAppDeletedSubscribers = new Set();
    this.designAppCreatedSubscribers = new Set();
    this.designAppDeletedSubscribers = new Set();

    if (id && this.persistenceFactory) {
      this.persistence = this.persistenceFactory(this.syncDoc, `semio-sketchpad-${id}`);
      this.persistence.once("synced", () => {
        const isMobile = typeof window !== "undefined" ? window.innerWidth < 768 : false;
        this.syncSketchpad.set("isMobile", isMobile);
      });
      if (this.remote) {
        this.remote.syncProvider(this.syncDoc, id);
      }
    }

    this.syncSketchpad = this.syncDoc.getMap("sketchpad");
    this.syncKits = this.syncDoc.getArray("kits");
    this.syncKitApps = this.syncDoc.getMap("kitApps");

    const syncTutorials = this.syncDoc.getMap("tutorials");
    this.tutorialStoreInstance = new TutorialStore(syncTutorials, (fn) => this.syncDoc.transact(fn));

    this.loadPersistedKits();

    this.syncDoc.transact(() => {
      if (!this.syncSketchpad.has("navigation")) {
        this.syncSketchpad.set("navigation", "/");
      }
      if (!this.syncSketchpad.has("navigationHistory")) {
        this.syncSketchpad.set("navigationHistory", JSON.stringify(["/"]));
      }
      if (!this.syncSketchpad.has("navigationHistoryIndex")) {
        this.syncSketchpad.set("navigationHistoryIndex", 0);
      }
      if (!this.syncSketchpad.has("recentSearches")) {
        this.syncSketchpad.set("recentSearches", JSON.stringify([]));
      }
      if (!this.syncSketchpad.has("recentFocusItems")) {
        this.syncSketchpad.set("recentFocusItems", JSON.stringify({}));
      }
      if (!this.syncSketchpad.has("theme")) {
        this.syncSketchpad.set("theme", Theme.SYSTEM);
      }
      if (!this.syncSketchpad.has("language")) {
        this.syncSketchpad.set("language", "en");
      }
      if (!this.syncSketchpad.has("device")) {
        this.syncSketchpad.set("device", JSON.stringify("desktop"));
      }
      if (!this.syncSketchpad.has("expertise")) {
        this.syncSketchpad.set("expertise", Expertise.BEGINNER);
      }
      if (!this.syncSketchpad.has("mode")) {
        this.syncSketchpad.set("mode", Mode.USER);
      }
      if (!this.syncSketchpad.has("isFullscreen")) {
        this.syncSketchpad.set("isFullscreen", false);
      }
      const isMobile = typeof window !== "undefined" ? window.innerWidth < 768 : false;
      this.syncSketchpad.set("isMobile", isMobile);
      if (!this.syncSketchpad.has("activeInteraction")) {
        this.syncSketchpad.set("activeInteraction", "");
      }
      if (!this.syncSketchpad.has("settings")) {
        this.syncSketchpad.set(
          "settings",
          JSON.stringify({
            apps: {
              design: {
                diagram: { proximityConnectDistance: 10 },
                scene: { gridSize: 24 },
              },
            },
          }),
        );
      }
      if (!this.syncSketchpad.has("panelSizes")) {
        this.syncSketchpad.set(
          "panelSizes",
          JSON.stringify({
            toolbarHeight: 52,
            toolsWidth: 230,
            hudWidth: 230,
            statsWidth: 230,
            detailsWidth: 230,
            consoleHeight: 200,
          }),
        );
      }
    });

    Object.entries(sketchpadCommands).forEach(([commandId, command]) => {
      this.registerCommand(commandId, command);
    });
    Object.entries(devCommands).forEach(([commandId, command]) => {
      this.registerCommand(commandId, command, { user: false });
    });

    if (initialState) {
      this.syncDoc.transact(() => {
        if (initialState.navigation !== undefined) this.syncSketchpad.set("navigation", initialState.navigation);
        if (initialState.navigationHistory !== undefined) this.syncSketchpad.set("navigationHistory", JSON.stringify(initialState.navigationHistory));
        if (initialState.navigationHistoryIndex !== undefined) this.syncSketchpad.set("navigationHistoryIndex", initialState.navigationHistoryIndex);
        if (initialState.recentSearches !== undefined) this.syncSketchpad.set("recentSearches", JSON.stringify(initialState.recentSearches));
        if (initialState.recentFocusItems !== undefined) this.syncSketchpad.set("recentFocusItems", JSON.stringify(initialState.recentFocusItems));
        if (initialState.theme !== undefined) this.syncSketchpad.set("theme", initialState.theme);
        if (initialState.language !== undefined) this.syncSketchpad.set("language", initialState.language);
        if (initialState.device !== undefined) this.syncSketchpad.set("device", JSON.stringify(initialState.device));
        if (initialState.expertise !== undefined) this.syncSketchpad.set("expertise", initialState.expertise);
        if (initialState.mode !== undefined) this.syncSketchpad.set("mode", initialState.mode);
        if (initialState.settings !== undefined) this.syncSketchpad.set("settings", JSON.stringify(initialState.settings));
        if (initialState.panelSizes !== undefined) this.syncSketchpad.set("panelSizes", JSON.stringify(initialState.panelSizes));
        if (initialState.isFullscreen !== undefined) this.syncSketchpad.set("isFullscreen", initialState.isFullscreen);
        if (initialState.hotkeyOverrides !== undefined) this.syncSketchpad.set("hotkeyOverrides", JSON.stringify(initialState.hotkeyOverrides));
        if (initialState.activeHotkeySetting !== undefined) this.syncSketchpad.set("activeHotkeySetting", initialState.activeHotkeySetting);
      });

      if (initialState.kits) {
        initialState.kits.forEach(({ kit, local, remote }) => {
          void this.createKit(kit, local, remote);
        });
      }
    }

    // When an injected KitStore is provided, register its kit in the store.
    // This allows Sketchpad to boot from an externally-provided KitStore
    // instead of creating an InMemoryKitStore internally.
    if (this.injectedKitStore) {
      const kitSnapshot = this.injectedKitStore.getSnapshot();
      const kit = kitSnapshot.kit;
      if (!this.kits.has(kit.guid)) {
        const inferredKitKind = this.inferKitPersistenceKind(this.injectedKitStore);
        this.registerKitStore(this.injectedKitStore, inferredKitKind.local, inferredKitKind.remote);
      }
    }
  }

  setActor = (actor: SketchpadActorRef) => {
    if (this.actorUnsubscribe) {
      this.actorUnsubscribe();
      this.actorUnsubscribe = undefined;
    }
    this.actor = actor;
    this.cache = undefined;
    this.cacheHash = undefined;
    if (this.id) {
      writeSketchpadStateToLocalStorage(this.id, actor.getSnapshot().context.sketchpad);
      const subscription = actor.subscribe((snapshot) => {
        writeSketchpadStateToLocalStorage(this.id!, snapshot.context.sketchpad);
      });
      this.actorUnsubscribe = () => subscription.unsubscribe();
    }
  };

  hash = (state: SketchpadState): string => {
    return JSON.stringify(state);
  };

  snapshot = (): SketchpadState => {
    if (this.actor) {
      return this.actor.getSnapshot().context.sketchpad;
    }
    const settingsStr = this.syncSketchpad.get("settings") as string;
    const settings = settingsStr
      ? JSON.parse(settingsStr)
      : {
        apps: {
          design: {
            diagram: { proximityConnectDistance: 10 },
            scene: { gridSize: 24 },
          },
        },
      };
    const panelSizesStr = this.syncSketchpad.get("panelSizes") as string;
    const panelSizes = panelSizesStr
      ? JSON.parse(panelSizesStr)
      : {
        toolbarHeight: 52,
        toolsWidth: 230,
        hudWidth: 230,
        statsWidth: 230,
        detailsWidth: 230,
        consoleHeight: 200,
      };
    const navigationHistoryStr = this.syncSketchpad.get("navigationHistory") as string;
    const navigationHistory = navigationHistoryStr ? JSON.parse(navigationHistoryStr).map(migratePath) : ["/"];
    const recentSearchesStr = this.syncSketchpad.get("recentSearches") as string;
    const recentSearches = recentSearchesStr ? JSON.parse(recentSearchesStr) : [];
    const recentFocusItemsStr = this.syncSketchpad.get("recentFocusItems") as string;
    const recentFocusItems = recentFocusItemsStr ? JSON.parse(recentFocusItemsStr) : {};
    const hotkeyOverridesStr = this.syncSketchpad.get("hotkeyOverrides") as string;
    const hotkeyOverrides = hotkeyOverridesStr ? JSON.parse(hotkeyOverridesStr) : {};
    const deviceStr = this.syncSketchpad.get("device") as string;
    const device: Device = deviceStr ? JSON.parse(deviceStr) : "desktop";
    const currentValues = {
      navigation: migratePath((this.syncSketchpad.get("navigation") as string) || "/"),
      navigationHistory: navigationHistory,
      navigationHistoryIndex: (this.syncSketchpad.get("navigationHistoryIndex") as number) ?? 0,
      recentSearches: recentSearches,
      recentFocusItems: recentFocusItems,
      theme: this.syncSketchpad.get("theme") as Theme,
      language: (this.syncSketchpad.get("language") as string) || "en",
      device: device,
      expertise: (this.syncSketchpad.get("expertise") as Expertise) ?? Expertise.BEGINNER,
      mode: (this.syncSketchpad.get("mode") as Mode) ?? Mode.USER,
      settings: settings,
      panelSizes: panelSizes,
      isFullscreen: (this.syncSketchpad.get("isFullscreen") as boolean) || false,
      isMobile: (this.syncSketchpad.get("isMobile") as boolean) || false,
      activeInteraction: (this.syncSketchpad.get("activeInteraction") as string) || undefined,
      hotkeyOverrides: hotkeyOverrides,
      activeHotkeySetting: (this.syncSketchpad.get("activeHotkeySetting") as string) || undefined,
    };
    const currentHash = this.hash(currentValues);
    if (!this.cache || this.cacheHash !== currentHash) {
      this.cache = currentValues;
      this.cacheHash = currentHash;
    }
    return this.cache;
  };

  private inferKitPersistenceKind = (kitStore: KitStore): { local: boolean; remote: boolean } => {
    const existingKind = (kitStore as any).__semioKitPersistenceKind as { local?: boolean; remote?: boolean } | undefined;
    if (existingKind) {
      return { local: Boolean(existingKind.local), remote: Boolean(existingKind.remote) };
    }
    const constructorName = (kitStore as any)?.constructor?.name ?? "";
    if (constructorName === "FolderKitStore" || constructorName === "JsonFileKitStore") {
      return { local: true, remote: false };
    }
    return { local: false, remote: false };
  };

  private registerKitStore = (kitStore: KitStore, local: boolean, remote: boolean) => {
    const registeredKit = kitStore.getSnapshot().kit;
    if (this.kits.has(registeredKit.guid)) {
      return;
    }
    (kitStore as any).__semioKitPersistenceKind = { local, remote };
    this.kits.set(registeredKit.guid, kitStore);

    kitStore.subscribe(() => {
      this.kitShallowsVersion++;
    });

    this.kitShallowsVersion++;
    this.kitCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  private createBackedKitStore = async (kit: Kit, local?: boolean, remote?: boolean): Promise<{ kitStore: KitStore; local: boolean; remote: boolean }> => {
    const localKitStoreFactory = this.folderKitStoreFactory ?? this.fileKitStoreFactory;
    if (remote && this.remoteKitStoreFactory) {
      return {
        kitStore: await this.remoteKitStoreFactory(kit),
        local: true,
        remote: true,
      };
    }
    if (local && localKitStoreFactory) {
      return {
        kitStore: await localKitStoreFactory(kit),
        local: true,
        remote: false,
      };
    }
    if (!local && !remote && this.temporaryKitStoreFactory) {
      return {
        kitStore: await this.temporaryKitStoreFactory(kit),
        local: false,
        remote: false,
      };
    }
    if (localKitStoreFactory) {
      return {
        kitStore: await localKitStoreFactory(kit),
        local: true,
        remote: false,
      };
    }
    return {
      kitStore: new InMemoryKitStore(kit),
      local: false,
      remote: false,
    };
  };

  availableKitKinds = (): SketchpadKitKindAvailability => {
    const hasConfiguredKitStoreFactories = Boolean(this.temporaryKitStoreFactory || this.folderKitStoreFactory || this.fileKitStoreFactory || this.remoteKitStoreFactory);
    if (!hasConfiguredKitStoreFactories && this.injectedKitStore) {
      const inferredKitKind = this.inferKitPersistenceKind(this.injectedKitStore);
      return {
        temporary: !inferredKitKind.local && !inferredKitKind.remote,
        local: inferredKitKind.local && !inferredKitKind.remote,
        remote: inferredKitKind.remote,
      };
    }
    return {
      temporary: hasConfiguredKitStoreFactories ? Boolean(this.temporaryKitStoreFactory) : true,
      local: Boolean(this.folderKitStoreFactory || this.fileKitStoreFactory),
      remote: Boolean(this.remoteKitStoreFactory),
    };
  };

  createKit = async (kit: Kit, local?: boolean, remote?: boolean) => {
    const createdKitStore = await this.createBackedKitStore(kit, local, remote);
    this.registerKitStore(createdKitStore.kitStore, createdKitStore.local, createdKitStore.remote);
  };

  private loadKitFilesFromPublic = async (kitGuid: string) => {
    try {
      const zipUrl = `/public/${kitGuid}.zip`;
      const response = await fetch(zipUrl);

      if (!response.ok) {
        return;
      }

      const blob = await response.blob();

      const JSZip = (await import("jszip")).default;
      const zip = await JSZip.loadAsync(blob);

      const filePromises: Promise<void>[] = [];
      zip.forEach((relativePath, zipEntry) => {
        if (!zipEntry.dir) {
          filePromises.push(
            zipEntry.async("blob").then(async (fileBlob) => {
              const file: SemioFile = {
                guid: guid(),
                name: relativePath.split("/").pop() || relativePath,
                size: fileBlob.size,
                hash: undefined,
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              };
              const loadKitStore = this.kits.get(kitGuid);
              if (loadKitStore) await executeKitCommand(loadKitStore, "semio.kit.addFile", "system.loadKitFiles", file, fileBlob);
            }),
          );
        }
      });

      await Promise.all(filePromises);
    } catch (error) { }
  };

  createKitApp = (kit: Guid) => {
    this.syncDoc.transact(() => {
      const kitStore = this.kit(kit);
      let syncKitApp = this.syncKitApps.get(kit) as SyncMap<SyncKitAppVal>;
      if (!syncKitApp) {
        syncKitApp = createSyncDocFactory()().createMap<SyncKitAppVal>();
        this.syncKitApps.set(kit, syncKitApp);
      }
      const kitAppFactory = getKitAppStoreFactory();
      const kitAppInstance = kitAppFactory(this, syncKitApp, (fn: () => void) => this.syncDoc.transact(fn), { kit });
      this.kitApps.set(kit, kitAppInstance);
    });
    this.kitAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  createDesignApp = (kit: Guid, design: Guid) => {
    const designAppFactory = getDesignAppStoreFactory();
    const designApp = designAppFactory(this, { kit, design });

    let designAppsMap = this.designApps.get(kit);
    if (!designAppsMap) {
      designAppsMap = new Map();
      this.designApps.set(kit, designAppsMap);
    }
    designAppsMap.set(design, designApp);
    this.designAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  change(diff: SketchpadDiff) {
    if (this.actor) {
      this.actor.send({ type: "CHANGE", diff });
      return;
    }
    this.syncDoc.transact(() => {
      if (diff.navigationHistory !== undefined) {
        this.syncSketchpad.set("navigationHistory", JSON.stringify(diff.navigationHistory));
      }
      if (diff.navigationHistoryIndex !== undefined) {
        this.syncSketchpad.set("navigationHistoryIndex", diff.navigationHistoryIndex);
      }
      if (diff.navigation) {
        this.syncSketchpad.set("navigation", diff.navigation);
      }
      if ("recentSearches" in diff) {
        this.syncSketchpad.set("recentSearches", JSON.stringify(diff.recentSearches || []));
      }
      if ("recentFocusItems" in diff) {
        const current = JSON.parse((this.syncSketchpad.get("recentFocusItems") as string) || "{}");
        this.syncSketchpad.set("recentFocusItems", JSON.stringify({ ...current, ...(diff.recentFocusItems || {}) }));
      }
      if (diff.theme) this.syncSketchpad.set("theme", diff.theme);
      if (diff.language !== undefined) {
        this.syncSketchpad.set("language", diff.language);
      }
      if (diff.device) this.syncSketchpad.set("device", JSON.stringify(diff.device));
      if (diff.expertise) this.syncSketchpad.set("expertise", diff.expertise);
      if (diff.mode) this.syncSketchpad.set("mode", diff.mode);
      if (diff.isFullscreen !== undefined) this.syncSketchpad.set("isFullscreen", diff.isFullscreen);
      if (diff.isMobile !== undefined) this.syncSketchpad.set("isMobile", diff.isMobile);
      if ("activeInteraction" in diff) this.syncSketchpad.set("activeInteraction", diff.activeInteraction || "");
      if (diff.settings) {
        const current = JSON.parse((this.syncSketchpad.get("settings") as string) || "{}");
        const merged = { ...current, apps: { ...current.apps, ...diff.settings.apps } };
        this.syncSketchpad.set("settings", JSON.stringify(merged));
      }
      if (diff.panelSizes) {
        const current = JSON.parse((this.syncSketchpad.get("panelSizes") as string) || "{}");
        this.syncSketchpad.set("panelSizes", JSON.stringify({ ...current, ...diff.panelSizes }));
      }
      if (diff.hotkeyOverrides) {
        const current = JSON.parse((this.syncSketchpad.get("hotkeyOverrides") as string) || "{}");
        this.syncSketchpad.set("hotkeyOverrides", JSON.stringify({ ...current, ...diff.hotkeyOverrides }));
      }
      if ("activeHotkeySetting" in diff) this.syncSketchpad.set("activeHotkeySetting", diff.activeHotkeySetting || "");
    });
  }

  deleteKit = (guid: Guid) => {
    const kitStore = this.kits.get(guid);
    if (kitStore) {
      this.syncDoc.transact(() => {
        const index = this.syncKits.toArray().findIndex((kitMeta) => kitMeta.get("guid") === guid);
        if (index !== -1) {
          this.syncKits.delete(index, 1);
        }
      });
      this.kits.delete(guid);
      this.kitShallowsVersion++;
      this.kitDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  deleteKitApp = (kit: Guid) => {
    const kitApp = this.kitApps.get(kit);
    if (kitApp) {
      this.kitApps.delete(kit);
      this.syncDoc.transact(() => {
        this.syncKitApps.delete(kit);
      });
      this.kitAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  deleteDesignApp = (kit: Guid, design: Guid) => {
    const designApp = this.designApps.get(kit)?.get(design);
    if (designApp) {
      this.designApps.get(kit)?.delete(design);
      if (this.designApps.get(kit)?.size === 0) {
        this.designApps.delete(kit);
      }
      this.designAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  onKitCreated = (callback: () => void): Unsubscribe => {
    this.kitCreatedSubscribers.add(callback);
    return () => {
      this.kitCreatedSubscribers.delete(callback);
    };
  };

  onKitAppCreated = (callback: () => void): Unsubscribe => {
    this.kitAppCreatedSubscribers.add(callback);
    return () => {
      this.kitAppCreatedSubscribers.delete(callback);
    };
  };

  onDesignAppCreated = (callback: () => void): Unsubscribe => {
    this.designAppCreatedSubscribers.add(callback);
    return () => {
      this.designAppCreatedSubscribers.delete(callback);
    };
  };

  onKitDeleted = (callback: () => void): Unsubscribe => {
    this.kitDeletedSubscribers.add(callback);
    return () => {
      this.kitDeletedSubscribers.delete(callback);
    };
  };

  onKitAppDeleted = (callback: () => void): Unsubscribe => {
    this.kitAppDeletedSubscribers.add(callback);
    return () => {
      this.kitAppDeletedSubscribers.delete(callback);
    };
  };

  onDesignAppDeleted = (callback: () => void): Unsubscribe => {
    this.designAppDeletedSubscribers.add(callback);
    return () => {
      this.designAppDeletedSubscribers.delete(callback);
    };
  };

  onChanged = (subscribe: Subscribe): Unsubscribe => {
    if (this.actor) {
      const subscription = this.actor.subscribe(() => {
        subscribe(() => { });
      });
      return () => subscription.unsubscribe();
    }
    return createObserver(this.syncSketchpad, subscribe);
  };

  onChangedDeep = (subscribe: Subscribe): Unsubscribe => {
    if (this.actor) {
      const subscription = this.actor.subscribe(() => {
        subscribe(() => { });
      });
      return () => subscription.unsubscribe();
    }
    return createObserver(this.syncSketchpad, subscribe, true);
  };

  async executeCommand<T>(command: string, ...args: any[]): Promise<T> {
    let origin: string | undefined;
    let rest: any[];

    if (typeof args[0] === "string" && args[0].startsWith("semio.sketchpad.")) {
      origin = args[0];
      rest = args.slice(1);
    } else {
      origin = undefined;
      rest = args;
    }

    this.tutorialStoreInstance.checkCommandCompletion(command, origin, rest);
    const tutorialState = this.tutorialStoreInstance.snapshot();
    if (tutorialState.recordingState === "recording") {
      this.tutorialStoreInstance.recordEvent({
        type: "command",
        data: { command, origin, args: rest },
      });
    }

    if (command === "semio.sketchpad.createKit") {
      const kit = rest[0] as Kit;
      const local = rest[1] as boolean | undefined;
      const remote = rest[2] as boolean | undefined;
      await this.createKit(kit, local, remote);
      return {} as T;
    }
    if (command === "semio.sketchpad.createKitApp") {
      const id = rest[0] as KitAppId;
      this.createKitApp(id.kit);
      return {} as T;
    }
    if (command === "semio.sketchpad.createDesignApp") {
      const id = rest[0] as DesignAppId;
      this.createDesignApp(id.kit, id.design);
      return {} as T;
    }
    if (command === "semio.sketchpad.importKit") {
      const Guid = rest[0] as Guid;
      const url = rest[1] as string;
      const kitStore = this.kits.get(Guid);
      if (kitStore) {
        await executeKitCommand(kitStore, "semio.kit.import", origin, url);
      }
      return {} as T;
    }
    if (command === "semio.sketchpad.freeze") {
      const completeState = this.dumpState();
      const stateJson = JSON.stringify(completeState, null, 2);
      const blob = new Blob([stateJson], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `semio-freeze-${new Date().toISOString().replace(/[:.]/g, "-")}.json`;
      a.click();
      URL.revokeObjectURL(url);
      return {} as T;
    }
    if (command === "semio.sketchpad.timetravel") {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = ".json";
      input.onchange = async (e: Event) => {
        const file = (e.target as HTMLInputElement).files?.[0];
        if (file) {
          const text = await file.text();
          const state = JSON.parse(text) as CompleteState;
          this.loadState(state);
        }
      };
      input.click();
      return {} as T;
    }
    if (command === "semio.sketchpad.copyJsonToClipboard") {
      const payload = rest.length > 1 ? rest[1] : undefined;
      let serializedState: unknown = payload;
      if (serializedState === undefined) {
        const navigation = this.snapshot().navigation ?? "";
        const activeKitGuid = navigation.match(/^\/kits\/([^/?#]+)/)?.[1] ?? navigation.match(/^\/kit\/([^/?#]+)/)?.[1];
        if (activeKitGuid && this.hasKit(activeKitGuid)) {
          serializedState = this.kit(activeKitGuid).getSnapshot().kit;
        } else {
          const firstKit = this.kits.values().next();
          serializedState = firstKit.done ? {} : firstKit.value.getSnapshot().kit;
        }
      }
      const stateJson = JSON.stringify(serializedState, null, 2);
      if (typeof navigator !== "undefined" && navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
        await navigator.clipboard.writeText(stateJson);
        return {} as T;
      }
      const textarea = document.createElement("textarea");
      textarea.value = stateJson;
      textarea.style.position = "fixed";
      textarea.style.left = "-9999px";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      return {} as T;
    }
    const callback = this.commandRegistry.get(command);
    if (!callback) {
      throw new Error(`Command "${command}" not found in sketchpad store`);
    }
    const context: SketchpadCommandContext = {
      sketchpad: this.snapshot(),
      origin,
    };
    const result = callback(context, ...rest);
    if (result.diff) {
      this.change(result.diff);
    }
    return result as T;
  }

  execute<T>(command: string, ...rest: any[]): Promise<T> {
    return this.executeCommand(command, ...rest);
  }

  registerCommand(command: string, callback: (context: SketchpadCommandContext, ...rest: any[]) => SketchpadCommandResult, metadata?: { user?: boolean }): Disposable {
    this.commandRegistry.set(command, callback);
    if (metadata) {
      this.commandMetadata.set(command, metadata);
    }
    return () => {
      this.commandRegistry.delete(command);
      this.commandMetadata.delete(command);
    };
  }

  isUserCommand(command: string): boolean {
    const metadata = this.commandMetadata.get(command);
    return metadata?.user !== false;
  }

  get commands() {
    return {
      execute: this.executeCommand.bind(this),
      register: this.registerCommand.bind(this),
      isUserCommand: this.isUserCommand.bind(this),
    };
  }

  dumpState(): CompleteState {
    const sketchpad = this.snapshot();

    const kits = Array.from(this.kits.entries()).map(([guid, kitStore]) => {
      const kitMetadataArray = this.syncKits.toArray();
      const kitMetadata = kitMetadataArray.find((m) => m.get("guid") === guid);
      return {
        guid,
        local: kitMetadata?.get("local") === true,
        remote: kitMetadata?.get("remote") === true,
        kit: kitStore.getSnapshot().kit,
      };
    });

    const kitApps: Record<string, any> = {};
    this.kitApps.forEach((app, guid) => {
      kitApps[guid] = app.snapshot();
    });

    const typeApps: Record<string, any> = {};
    this.typeApps.forEach((app, key) => {
      typeApps[key] = app.snapshot();
    });

    const qualityApps: Record<string, any> = {};
    this.qualityApps.forEach((app, key) => {
      qualityApps[key] = app.snapshot();
    });

    const designApps: Record<string, Record<string, any>> = {};
    this.designApps.forEach((designMap, kitGuid) => {
      designApps[kitGuid] = {};
      designMap.forEach((app, designGuid) => {
        designApps[kitGuid][designGuid] = app.snapshot();
      });
    });

    const home = this.homeStore?.snapshot();
    const tutorials = this.tutorialStoreInstance.snapshot();

    return {
      sketchpad,
      kits,
      kitApps,
      typeApps,
      qualityApps,
      designApps,
      home,
      tutorials,
    };
  }

  loadState(state: CompleteState): void {
    this.syncDoc.transact(() => {
      this.kits.clear();
      this.kitApps.clear();
      this.typeApps.clear();
      this.qualityApps.clear();
      this.designApps.clear();

      this.syncKits.delete(0, this.syncKits.length);
      this.syncKitApps.forEach((_, key) => this.syncKitApps.delete(key));

      this.syncSketchpad.set("navigation", state.sketchpad.navigation);
      this.syncSketchpad.set("navigationHistory", JSON.stringify(state.sketchpad.navigationHistory));
      this.syncSketchpad.set("navigationHistoryIndex", state.sketchpad.navigationHistoryIndex);
      this.syncSketchpad.set("recentSearches", JSON.stringify(state.sketchpad.recentSearches));
      this.syncSketchpad.set("recentFocusItems", JSON.stringify(state.sketchpad.recentFocusItems));
      this.syncSketchpad.set("theme", state.sketchpad.theme);
      this.syncSketchpad.set("device", JSON.stringify(state.sketchpad.device));
      this.syncSketchpad.set("expertise", state.sketchpad.expertise);
      this.syncSketchpad.set("mode", state.sketchpad.mode);
      this.syncSketchpad.set("settings", JSON.stringify(state.sketchpad.settings));
      this.syncSketchpad.set("panelSizes", JSON.stringify(state.sketchpad.panelSizes));
      this.syncSketchpad.set("isFullscreen", state.sketchpad.isFullscreen);
      this.syncSketchpad.set("isMobile", state.sketchpad.isMobile);
      if (state.sketchpad.activeInteraction) {
        this.syncSketchpad.set("activeInteraction", state.sketchpad.activeInteraction);
