          const { kit } = await importKit(url);

          await store.execute("semio.sketchpad.createKit", "semio.sketchpad.importKitUrls", kit, false, false);
        } catch (error) {
          console.error(`[Sketchpad] Failed to auto-import kit from ${url}:`, error);
