// [👤semio📚js🗃️sketchpad💻sketchpad🔖sketchpadcomponents](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Sketchpad%20Components)
// Top-level sketchpad React components for rendering the complete application.

// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨toolbarscopewrapper](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/ToolbarScopeWrapper)
/**
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨toolbarscopewrapper](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/ToolbarScopeWrapper)
 * ToolbarScopeWrapper holds the data fields for a ToolbarScopeWrapper record.
 **/
const ToolbarScopeWrapper: FC<{ children: ReactNode }> = ({ children }) => {
  const location = useLocation();
  const scopeGuids = useMemo(() => {
    const pathMatch = location.pathname.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
    return {
      kit: pathMatch?.[1],
      itemType: pathMatch?.[2],
      item: pathMatch?.[3],
    };
  }, [location.pathname]);

  const { kit, itemType, item } = scopeGuids;
  let wrapped = <>{children}</>;

  if (item && kit) {
    if (itemType === "qualities") {
      wrapped = <QualityScopeProvider guid={item}>{wrapped}</QualityScopeProvider>;
    } else if (itemType === "types") {
      wrapped = <TypeScopeProvider guid={item}>{wrapped}</TypeScopeProvider>;
    } else if (itemType === "designs") {
      wrapped = <DesignScopeProvider guid={item}>{wrapped}</DesignScopeProvider>;
    }
  }
  if (kit) {
    wrapped = <KitScopeProvider guid={kit}>{wrapped}</KitScopeProvider>;
  }

  return wrapped;
};

const PanelTabContent: FC<{ sections: PanelSection[] }> = ({ sections }) => {
  const sortedSections = [...sections].sort((a, b) => (a.order || 0) - (b.order || 0));
  const treeSections = sortedSections.map((section, index) => ({
    id: section.id,
    defaultOpen: section.defaultOpen ?? index === 0,
    actions: section.actions,
    onPointerEnter: section.onPointerEnter,
    onPointerLeave: section.onPointerLeave,
    onDoubleClick: section.onDoubleClick,
    content: typeof section.content === "function" ? section.content() : section.content,
  }));

  return (
    <TreeStateProvider>
      <Tree className="min-w-0 overflow-hidden" sections={treeSections} />
    </TreeStateProvider>
  );
};

const DynamicPanelTabContent: FC<{ panelKey: PanelKey }> = ({ panelKey }) => {
  const sections = usePanelSections(panelKey);
  return <PanelTabContent sections={sections} />;
};

