  const setter = useMemo(
    () => (next: T) => {
      if (canSet) {
        actor.send(createSendEvent(kitGuid, designGuid, next) as Parameters<typeof actor.send>[0]);
      }
    },
    [actor, kitGuid, designGuid, canSet, createSendEvent],
  );
