 **/
const HomeTableWindow = memo(() => {
  return <HomeTableContent />;
});
HomeTableWindow.displayName = "HomeTableWindow";

// [👤semio📚js🗃️sketchpad💻home🔖app🔖multiwindowapp🪨home](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/s/Multi-Window%20App/d/i/Home)
/**
 * [👤semio📚js🗃️sketchpad💻home🔖app🔖multiwindowapp🪨home](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/s/Multi-Window%20App/d/i/Home)
 * Home holds the data fields for a Home record.
 **/
const Home: FC = () => {
  const actor = useSketchpadActor();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const isMobile = useIsMobile();
  const availableKitKinds = useAvailableKitKinds();

  const homeState = useHome() as HomeState;
  const storedWindowLayout = homeState?.windowLayout;

  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "home") return;

    const hasAvailableKitKinds = availableKitKinds.temporary || availableKitKinds.local || availableKitKinds.remote;

    if (hasAvailableKitKinds) {
      addSection("toolbar", {
        id: "semio.sketchpad.app.home.toolbar.filters",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "filter",
          labelId: "semio.sketchpad.toolbar.parent.filter",
          order: 20,
        },
        content: <HomeToolbarFilters />,
      });
      addSection("toolbar", {
        id: "semio.sketchpad.app.home.toolbar.create",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "create",
          labelId: "semio.sketchpad.toolbar.parent.create",
          order: 30,
        },
        content: <HomeToolbarCreate />,
      });
    }

    return () => {
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.filters");
      removeSection("toolbar", "semio.sketchpad.app.home.toolbar.create");
    };
  }, [appType, addSection, removeSection, availableKitKinds]);

  // Add Settings and Chat as side panel tabs
  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();

  useEffect(() => {
    if (appType !== "home") return;

    addSidePanelTab("right", {
      id: "semio.sketchpad.app.home.settings",
      icon: SettingsIcon,
      order: 100,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.home.settings.content", label: null, content: <SettingsContent /> }]} />
        </TreeStateProvider>
      ),
    });

    addSidePanelTab("right", {
      id: "semio.sketchpad.app.home.chat",
      icon: ChatIcon,
      order: 101,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.home.chat.content", label: null, content: <ChatPlaceholder /> }]} />
        </TreeStateProvider>
      ),
    });

    return () => {
      removeSidePanelTab("right", "semio.sketchpad.app.home.settings");
      removeSidePanelTab("right", "semio.sketchpad.app.home.chat");
    };
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: HomeAppWindowKind.Table,
                title: "table",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );

  const windowLayout = useMemo(() => storedWindowLayout || defaultLayout, [storedWindowLayout, defaultLayout]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: HomeAppWindowKind.Table,
          label: "table",
          component: () => <HomeTableWindow />,
        },
      ],
      defaultLayout,
    }),
    [defaultLayout],
  );

  const handleLayoutChange = useCallback(
    (config: any) => {
      const configStr = JSON.stringify(config);
      const lastStr = JSON.stringify(lastLayoutRef.current);
      if (configStr === lastStr) return;
    },
    [actor],
  );

  if (isMobile) {
    return (
      <HomeDropZone>
        <HomeTableContent />
      </HomeDropZone>
    );
  }

  return (
    <>
      <HomeFooter />
      <HomeDropZone>
        <Canvas id="semio.sketchpad.app.home.canvas">
          <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
        </Canvas>
      </HomeDropZone>
    </>
  );
};

