            {progress.current + 1}/{progress.total}
          </span>
        </div>
        {currentMilestone && <div className="text-xs truncate text-muted mt-1">{currentMilestone.title}</div>}
      </div>
      <div className="text-xs text-muted">{tutorial.name}</div>
    </div>
  );
};

