 **/
export function useKitTransaction(): Transaction {
  const store = useSketchpadStore();
  const kitScope = useKitScope();
  const kitGuid = kitScope?.guid;

  if (!kitGuid || !store.hasKit(kitGuid)) {
    return {};
  }

  return {
    start: () => {},
    finalize: () => {},
    abort: () => {},
  };
}

