        .map((t) => `${t.guid}:${t.name}:${t.parent?.guid || ""}:${t.folder || ""}:${t.updatedAt || ""}`)
        .join("|"),
    [kitTypes],
  );
  const kitQualitiesKey = useMemo(
    () =>
      (kitQualities ?? [])
        .filter(Boolean)
        .map((q) => `${q.guid}:${q.name}:${q.folder || ""}`)
        .join("|"),
    [kitQualities],
  );
  const kitPortsKey = useMemo(
    () =>
      (kitPorts ?? [])
