// [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖table🪨app](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/App)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨app](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/KitTableApp)
 **/
const KitTableApp: FC = () => {
  useKitAppYjsToXStateSync();
  const transaction = useKitAppTransaction();
  const { undo, redo, deleteSelected } = useKitAppCommands();
  useHotkeys("ctrl+z", () => undo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+y", () => redo?.(), { enableOnFormTags: true });
  useHotkeys("ctrl+shift+z", () => redo?.(), { enableOnFormTags: true });
  useHotkeys("delete,backspace", () => deleteSelected?.(), { enableOnFormTags: true });

  return (
    <ErrorBoundary
      fallback={
        <div className="flex items-center justify-center h-full">
          <p className="text-sm text-muted-foreground">Failed to load kit app</p>
        </div>
      }
    >
      <TransactionProvider transaction={transaction}>
        <KitDropZone>
          <Canvas>
            <Window id="kit-table">
              <AppContent />
            </Window>
          </Canvas>
        </KitDropZone>
      </TransactionProvider>
    </ErrorBoundary>
  );
};

