 **/
const performanceLogTimestamps = new Map<string, number>();

/**
 * Enables or disables performance logging for store operations.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️enableperformancelogging](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/enablePerformanceLogging)
 **/
export function enablePerformanceLogging(enabled: boolean = true) {
  performanceLoggingEnabled = enabled;
  if (!enabled) {
    performanceLogCounts.clear();
    performanceLogTimestamps.clear();
  }
}

/** logStateAccess holds the data fields for a logStateAccess record.
 **/
// [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️logstateaccess](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/logStateAccess)
/**
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖apps🔖sketchpad🪨logstateaccess](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps/s/Sketchpad/d/i/logStateAccess)
 **/
function logStateAccess(hookName: string, storeType: string, selectorInfo?: string) {
  if (!performanceLoggingEnabled) return;
  const key = `${hookName}:${storeType}${selectorInfo ? `:${selectorInfo}` : ""}`;
  const count = (performanceLogCounts.get(key) || 0) + 1;
  performanceLogCounts.set(key, count);
  const now = Date.now();
  const lastTime = performanceLogTimestamps.get(key) || 0;
  performanceLogTimestamps.set(key, now);
  if (now - lastTime < 100) {
    console.warn(`[PERF] Rapid re-render: ${key} (${count}x, ${now - lastTime}ms apart)`);
  }
}

/**
