    } else {
      root.classList.remove("touch");
    }
  }, [device]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    if (isFullscreen) {
      root.classList.add("fullscreen");
    } else {
      root.classList.remove("fullscreen");
    }
  }, [isFullscreen]);

  const navigationHistory = useNavigationHistory();
  const currentPath = `${navigation}${location.search}`;
  const [searchParams] = useSearchParams();
  const kits = useKits() ?? [];

  const pathParts = navigation.split("/").filter((p) => p);
  const isUuidPattern = (str: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str);
  const isKitsPath = pathParts[0] === "kits";
  const isDocsPath = pathParts[0] === "docs";
  const kitGuid = isKitsPath && pathParts[1] ? pathParts[1] : null;
  const secondPart = pathParts[2];
  const thirdPart = pathParts[3];
  const isDesignApp = isKitsPath && secondPart === "designs" && thirdPart && isUuidPattern(thirdPart);
  const isTypeApp = isKitsPath && secondPart === "types" && thirdPart && isUuidPattern(thirdPart);
  const isQualityApp = isKitsPath && secondPart === "qualities" && thirdPart && isUuidPattern(thirdPart);
  const isKitApp = kitGuid && !isDesignApp && !isTypeApp && !isQualityApp;

  const kitFromScope = useKit();
  const designFromScope = useDesign();
  const typeFromScope = useType();
  const kit: Kit | KitShallow | null | undefined = (kitFromScope as Kit | KitShallow | null | undefined) || kits.find((k) => k.guid === kitGuid);
  const kitKind = useKitKind(kitGuid || "");

  const itemGuid = isDesignApp || isTypeApp || isQualityApp ? thirdPart : null;
  const allDesigns: Design[] = useMemo(() => {
    if (!kit?.designs) return [];
    return (kit.designs as any[]).filter((d): d is Design => typeof d === "object" && d.guid !== undefined);
  }, [kit?.designs]);
  const allTypes: Type[] = useMemo(() => {
    if (!kit?.types) return [];
    return (kit.types as any[]).filter((t): t is Type => typeof t === "object" && t.guid !== undefined);
  }, [kit?.types]);

  const design = useMemo(() => {
    if (isDesignApp && itemGuid) {
      return designFromScope || allDesigns.find((d) => d.guid === itemGuid) || null;
    }
    return null;
  }, [isDesignApp, itemGuid, designFromScope, allDesigns]);

  const type = useMemo(() => {
    if (isTypeApp && itemGuid) {
      return typeFromScope || allTypes.find((t) => t.guid === itemGuid) || null;
    }
    return null;
  }, [isTypeApp, itemGuid, typeFromScope, allTypes]);

  const homeKind = !isKitsPath || pathParts.length === 1 ? (searchParams.get("kind") as "temporary" | "local" | "remote" | null) : null;
  const homeName = !isKitsPath || pathParts.length === 1 ? searchParams.get("name") : null;
  const homeVersion = !isKitsPath || pathParts.length === 1 ? searchParams.get("version") : null;
  const filteredKind = kitGuid && !isDesignApp && !isTypeApp && !isQualityApp ? (searchParams.get("kind") as "designs" | "types" | "qualities" | "files" | "authors" | null) : null;
  const filteredName = kitGuid && !isDesignApp && !isTypeApp && !isQualityApp ? searchParams.get("name") : null;

  const upTarget = useMemo(() => {
    const pathWithoutQuery = currentPath.split("?")[0];

    if (homeKind) {
      if (homeVersion !== null && homeName) {
        const params = new URLSearchParams();
        params.set("kind", homeKind);
        params.set("name", homeName);
        return `/?${params.toString()}`;
      }
      if (homeName) {
        const params = new URLSearchParams();
        params.set("kind", homeKind);
        return `/?${params.toString()}`;
      }
      return "/";
    }

    if (pathWithoutQuery === "/") return undefined;
    if (pathWithoutQuery === "/kits") return "/";

    if (isDesignApp && design && typeof design === "object" && "parent" in design) {
      const designObj = design as Design;
      if (designObj.parent) {
        return `/kits/${kitGuid}/designs/${designObj.parent}`;
      }
      return `/kits/${kitGuid}?kind=designs`;
    }

    if (isTypeApp && type && typeof type === "object" && "parent" in type) {
      const typeObj = type as Type;
      if (typeObj.parent) {
        return `/kits/${kitGuid}/types/${typeObj.parent}`;
      }
      return `/kits/${kitGuid}?kind=types`;
    }

    if (isQualityApp) {
      return `/kits/${kitGuid}?kind=qualities`;
    }

    if (isKitApp) {
      if (filteredKind) {
        const kitObj = kit && typeof kit === "object" && "name" in kit ? (kit as Kit) : null;
        if (kitKind && kitObj) {
          const params = new URLSearchParams();
          params.set("kind", kitKind);
          if (kitObj.name) params.set("name", kitObj.name);
          if (kitObj.version !== undefined && kitObj.version !== null) {
            params.set("version", kitObj.version);
          }
          return `/?${params.toString()}`;
        }
        return `/kits/${kitGuid}`;
      }
      if (kitGuid && kitKind) {
        const kitObj = kit && typeof kit === "object" && "name" in kit ? (kit as Kit) : null;
        if (kitObj) {
          const params = new URLSearchParams();
          params.set("kind", kitKind);
          if (kitObj.name) params.set("name", kitObj.name);
          if (kitObj.version !== undefined && kitObj.version !== null) {
            params.set("version", kitObj.version);
          }
          return `/?${params.toString()}`;
        }
        return `/?kind=${kitKind}`;
      }
      return "/";
    }

    return pathWithoutQuery.split("/").slice(0, -1).join("/") || "/";
  }, [currentPath, isDesignApp, isTypeApp, isQualityApp, isKitApp, design, type, kitGuid, filteredKind, filteredName, kitKind, kit, homeKind, homeName, homeVersion]);
  const isAtRoot = currentPath === "/" || (currentPath === "/kits" && !kitGuid);

  // Fixed navbar layout matching UI defaults: [breadcrumb (flex-1)] [search] [find] [panelToggles]
  // Navigation buttons are integrated into the breadcrumb area.
  const navbarItems = useMemo(() => {
    const items: NavbarItem[] = [];
    items.push({
      key: "breadcrumb",
      className: "flex-1 min-w-0",
      content: (
        <div className="flex items-center h-full min-w-0">
          <ButtonGroup id="semio.sketchpad.navbar.navigationButtons">
            <ButtonGroupItem value="back" id="semio.sketchpad.navbar.back" onClick={() => sketchpadCommands.navigateBack("semio.sketchpad.navbar.back")} disabled={!navigationHistory.canGoBack}>
              <NavigateBackIcon size={16} />
            </ButtonGroupItem>
            <ButtonGroupItem value="forward" id="semio.sketchpad.navbar.forward" onClick={() => sketchpadCommands.navigateForward("semio.sketchpad.navbar.forward")} disabled={!navigationHistory.canGoForward}>
              <NavigateForwardIcon size={16} />
            </ButtonGroupItem>
            <ButtonGroupItem
              value="up"
              id="semio.sketchpad.navbar.up"
              onClick={() => {
                if (upTarget) navigate(upTarget);
              }}
              disabled={isAtRoot}
            >
              <NavigateUpIcon size={16} />
            </ButtonGroupItem>
          </ButtonGroup>
          <div className="flex-1 min-w-0">
            <Navigation />
          </div>
        </div>
      ),
    });
    items.push({ key: "search", content: <Search /> });
    items.push({ key: "focus", content: <Focus /> });
    items.push({ key: "panelToggles", content: <PanelToggles /> });
    return items;
  }, [navigationHistory, upTarget, isAtRoot, navigate, sketchpadCommands]);

  const activeInteraction = useActiveInteraction();
  const panelOpacity = activeInteraction === "dragging" ? 0.3 : 1;
  const rightSidePanelElementSizingClassName = [
    "[&_[data-slot='side-panel-tabs']]:h-medium",
    "[&_[data-slot='side-panel-tab-button']]:px-small",
    "[&_[data-slot='side-panel-tab-button']_svg]:size-small",
    "[&_[data-slot='side-panel-content']]:p-[10px]",
    "[&_[data-slot='tree-item-row']]:min-h-[24px]",
    "[&_[data-slot='tree-item-row']]:py-0",
    "[&_[data-slot='tree-item-row']]:items-center",
    "[&_[data-slot='tree-section-row']]:h-[20px]",
    "[&_[data-slot='tree-section-row']]:py-0",
    "[&_[data-slot='tree-section-row']]:mt-[12px]",
    "[&_[data-slot='tree-label']]:text-xs",
    "[&_[data-slot='tree-label']]:tracking-[0.04em]",
    "[&_[data-slot='property-row']]:min-h-[24px]",
    "[&_[data-slot='property-row']]:grid-cols-[96px_minmax(0,1fr)]",
    "[&_[data-slot='property-row']]:gap-x-[8px]",
    "[&_[data-slot='property-label']]:min-w-0",
    "[&_[data-slot='property-label']]:px-0",
    "[&_[data-slot='property-label']]:text-xs",
    "[&_[data-slot='property-label']]:font-normal",
    "[&_[data-slot='input']]:!h-[22px]",
    "[&_[data-slot='input']]:rounded-[3px]",
    "[&_[data-slot='input']]:px-[6px]",
    "[&_[data-slot='input']]:text-xs",
    "[&_[data-slot='select-trigger']]:!h-[22px]",
    "[&_[data-slot='select-trigger']]:w-full",
    "[&_[data-slot='select-trigger']]:rounded-[3px]",
    "[&_[data-slot='select-trigger']]:px-[6px]",
    "[&_[data-slot='select-trigger']]:text-xs",
    "[&_[data-slot='select-trigger']_svg]:size-[12px]",
    "[&_[data-slot='stepper-group']]:h-[22px]",
    "[&_[data-slot='stepper-group']]:w-[100px]",
    "[&_[data-slot='stepper-group']]:rounded-[3px]",
    "[&_[data-slot='stepper-minus']]:h-[22px]",
    "[&_[data-slot='stepper-minus']]:w-[22px]",
    "[&_[data-slot='stepper-plus']]:h-[22px]",
    "[&_[data-slot='stepper-plus']]:w-[22px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!h-[22px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!w-[56px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!min-w-[56px]",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!px-0",
    "[&_[data-slot='slider-row']]:items-center",
    "[&_[data-slot='slider-row']]:gap-x-[8px]",
    "[&_[data-slot='slider-value']]:w-[28px]",
    "[&_[data-slot='slider-value']]:text-right",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!px-0",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!w-[28px]",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!min-w-[28px]",
    "[&_[data-slot='button-group-item']]:h-medium",
    "[&_[data-slot='textarea']]:text-xs",
    "[&_[data-slot='textarea']]:rounded-[3px]",
    "[&_[data-slot='textarea']]:px-[6px]",
    "[&_[data-slot='textarea']]:py-[3px]",
    "[&_[data-slot='textarea']]:min-h-[44px]",
    "[&_[role='combobox']]:!h-[22px]",
    "[&_[role='combobox']]:rounded-[3px]",
    "[&_[role='combobox']]:px-[6px]",
    "[&_[role='combobox']]:text-xs",
    "[&_[role='combobox']_svg]:size-[12px]",
  ].join(" ");

  const [activeDragId, setActiveDragId] = useState<string | null>(null);
  const [activeDragData, setActiveDragData] = useState<any>(null);
  const [activeToolbarGroup, setActiveToolbarGroup] = useState<string | null>(null);

  const toolbarGroups = useMemo(() => {
    const groups: Record<string, PanelSection[]> = {};
    toolbarSections.forEach((section) => {
      const gid = section.toolbarGroup?.id;
      if (gid) {
        if (!groups[gid]) groups[gid] = [];
        groups[gid].push(section);
      }
    });

    Object.keys(groups).forEach((key) => {
      groups[key].sort((a, b) => (a.toolbarGroup?.order ?? 0) - (b.toolbarGroup?.order ?? 0));
    });
    return groups;
  }, [toolbarSections]);

  useEffect(() => {
    const groupOrder = ["hand", "selection", "filter", "create", "view", "actions"];
    const firstGroup = groupOrder.find((g) => g !== "hand" && toolbarGroups[g]);
    setActiveToolbarGroup((prev) => (prev === null || (prev !== null && !toolbarGroups[prev]) ? (firstGroup ?? null) : prev));
  }, [toolbarGroups]);

  const toolbarGroupsRef = useRef(toolbarGroups);
  toolbarGroupsRef.current = toolbarGroups;
  const toggleToolbarGroup = useCallback((id: string) => {
    setActiveToolbarGroup((prev) => {
      const next = prev === id ? null : id;
      if (next) {
        queueMicrotask(() => {
          const groups = toolbarGroupsRef.current;
          if (groups[next]) {
            for (const section of groups[next]) {
              section.toolbarGroup?.onActivate?.();
            }
          }
        });
      }
      return next;
    });
  }, []);

  const [activeSubToolByGroup, setActiveSubToolByGroup] = useState<Record<string, string>>({});

  const setSubTool = useCallback((groupId: string, subToolId: string) => {
    setActiveSubToolByGroup((prev) => ({ ...prev, [groupId]: subToolId }));
    setActiveToolbarGroup(groupId);
  }, []);

  const getGroupIcon = useCallback((groupId: string) => {
    switch (groupId) {
      case "hand":
        return <HandIcon className="size-tiny" />;
      case "selection":
        return <MousePointerIcon className="size-tiny" />;
      case "filter":
        return <SearchIcon className="size-tiny" />;
      case "create":
        return <AddIcon className="size-tiny" />;
      case "view":
        return <LayoutIcon className="size-tiny" />;
      case "actions":
        return <MoreHorizontalIcon className="size-tiny" />;
      default:
        return <FocusIcon className="size-tiny" />;
    }
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
  );

  const customCollisionDetection = useCallback((args: any) => {
    const pointerCollisions = pointerWithin(args);

    if (pointerCollisions.length > 0) {
      return pointerCollisions;
    }

    const rectCollisions = rectIntersection(args);

    if (rectCollisions.length > 0) {
      return rectCollisions;
    }

    const centerCollisions = closestCenter(args);

    if (centerCollisions && centerCollisions.length > 0) {
      return centerCollisions;
    }
    return [];
  }, []);
  const kitShallows = useKitShallows();
  const getTypeOrDesignName = useCallback(() => {
    if (!activeDragData) return null;
    if (activeDragData.type === "type") {
      const kitId = activeDragData.typeGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const type = kit?.types?.find((t: any) => typeof t === "object" && t.guid === activeDragData.typeGuid) as any;
      return type?.name || "Type";
    } else if (activeDragData.type === "design") {
      const kitId = activeDragData.designGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const design = kit?.designs?.find((d: any) => typeof d === "object" && d.guid === activeDragData.designGuid) as any;
      return design?.name || "Design";
    }
    return null;
  }, [activeDragData, kitShallows]);
  return (
    <TutorialProvider store={tutorialStore}>
      <GlobalFooterItems />
      <DndContext
        sensors={sensors}
        collisionDetection={customCollisionDetection}
        onDragStart={(event) => {
          setActiveDragId(event.active.id as string);
          setActiveDragData(event.active.data.current);

          sketchpadCommands.setActiveInteraction("semio.sketchpad.drag", "dragging");
        }}
        onDragEnd={(event) => {
          setActiveDragId(null);
          setActiveDragData(null);

          sketchpadCommands.setActiveInteraction("semio.sketchpad.drag", undefined);

          const customEvent = new CustomEvent("design-drag-end", { detail: event });
          window.dispatchEvent(customEvent);
        }}
      >
        <LevelProvider level="base">
          <ToolbarScopeWrapper>
            <LayoutComponent
              className="bg-base text-foreground relative border"
              navbar={<Navbar items={navbarItems} />}
              footer={
                <Footer
                  items={footerItems.map((item) => ({
                    id: item.id,
                    icon: item.icon,
                    text: item.text,
                    content: item.content,
                    order: item.order,
                    onClick: item.onClick,
                  }))}
                  isVisible={isFooterExpanded || !isFullscreen}
                />
              }
              bottomPanel={
                consoleSections.length > 0
                  ? {
                      visible: true,
                      size: panelSizes.consoleHeight,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "consoleHeight", size),
                      sections: consoleSections,
                      panelKey: "console",
                    }
                  : undefined
              }
              leftSidePanel={
                leftSidePanelTabs.length > 0 && panelVisibility.leftSidePanel
                  ? {
                      position: "left" as const,
                      visible: true,
                      size: panelSizes.leftSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "leftSidePanelWidth", size),
                      tabs: leftSidePanelTabs,
                      activeTabId: activeLeftTabId,
                      onActiveTabChange: setActiveLeftTabId,
                    }
                  : undefined
              }
              rightSidePanel={
                rightSidePanelTabs.length > 0 && panelVisibility.rightSidePanel
                  ? {
                      position: "right" as const,
                      visible: true,
                      size: panelSizes.rightSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "rightSidePanelWidth", size),
                      tabs: rightSidePanelTabs,
                      activeTabId: activeRightTabId,
                      onActiveTabChange: setActiveRightTabId,
                      minSize: 150,
                      maxSize: 500,
                      className: rightSidePanelElementSizingClassName,
                    }
                  : undefined
              }
              toolbar={
                panelVisibility.toolbar || appType === "type" || appType === "design" || appType === "feedback" || appType === "kit" || appType === "home" || appType === "quality" || appType === "docs" ? (
                  toolbarSections.length > 0 ? (
                    <div role="toolbar" id="semio.sketchpad.toolbar" className="absolute bottom-1.5 left-0 right-0 h-[40px] pointer-events-none px-2">
                      <div id="semio.sketchpad.toolbar.seam" className="absolute left-1/2 top-0 h-full w-0 -translate-x-1/2">
                        <div id="semio.sketchpad.toolbar.zone.tools" className="absolute right-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                          <LevelProvider level="panel">
                            <ToolbarZone>
                              {["hand", "selection", "filter", "create", "view", "actions"].map((groupId) => {
                                if (!toolbarGroups[groupId]) return null;
                                const isActive = activeToolbarGroup === groupId;

                                if (groupId === "selection") {
                                  const activeSubToolId = activeSubToolByGroup[groupId] || toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                  const uniqueSubTools = Array.from(new Set(toolbarGroups[groupId].map((s) => s.toolbarGroup?.subToolId).filter(Boolean))) as string[];
                                  if (uniqueSubTools.length === 0) {
                                    return (
                                      <Toggle
                                        key={groupId}
                                        kind="single"
                                        id={`semio.sketchpad.toolbar.group.${groupId}`}
                                        pressed={isActive}
                                        onPressedChange={() => toggleToolbarGroup(groupId)}
                                        icon={getGroupIcon(groupId)}
                                        text={i18n.t(`semio.sketchpad.toolbar.parent.${groupId}`)}
                                      />
                                    );
                                  }

                                  return (
                                    <Toggle
                                      key={groupId}
                                      kind="dropdown"
                                      id={`semio.sketchpad.toolbar.group.${groupId}`}
                                      value={activeSubToolId}
                                      pressed={isActive}
                                      onPressedChange={(pressed) => {
                                        setActiveToolbarGroup(pressed ? groupId : null);
                                      }}
                                      onValueChange={(val) => val && setSubTool(groupId, val)}
                                      dropdownSide="top"
                                      dropdownAlign="end"
                                      dropdownSideOffset={2}
                                      dropdownAvoidCollisions={false}
                                      dropdownInstant={true}
                                      dropdownContentClassName="w-[10.5rem] min-w-[10.5rem] p-0 overflow-hidden border transition-none"
                                      items={uniqueSubTools.map((subToolId) => {
                                        const section = toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId === subToolId);
                                        return {
                                          value: subToolId,
                                          label: section?.toolbarGroup?.subToolIcon || <FocusIcon className="size-tiny" />,
                                          text: section?.toolbarGroup?.subToolLabelId ? i18n.t(section.toolbarGroup.subToolLabelId) : subToolId,
                                          id: `semio.sketchpad.toolbar.subtool.${subToolId}`,
                                        };
                                      })}
                                    />
                                  );
                                }

                                return (
                                  <Toggle
                                    key={groupId}
                                    kind="single"
                                    id={`semio.sketchpad.toolbar.group.${groupId}`}
                                    pressed={isActive}
                                    onPressedChange={() => toggleToolbarGroup(groupId)}
                                    icon={getGroupIcon(groupId)}
                                    text={i18n.t(`semio.sketchpad.toolbar.parent.${groupId}`)}
                                  />
                                );
                              })}
                            </ToolbarZone>
                          </LevelProvider>
                        </div>

                        {activeToolbarGroup && toolbarGroups[activeToolbarGroup] && (
                          <div id="semio.sketchpad.toolbar.zone.settings" className="absolute left-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                            <LevelProvider level="panel">
                              <ToolbarZone className="flex-nowrap min-w-0">
                                <ToolbarScopeWrapper>
                                  {toolbarGroups[activeToolbarGroup]?.map((section) => {
                                    if (activeToolbarGroup === "selection") {
                                      const activeSubToolId = activeSubToolByGroup["selection"] || toolbarGroups["selection"].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                      const hasSelectionSubTools = toolbarGroups["selection"]?.some((s) => Boolean(s.toolbarGroup?.subToolId));
                                      if (hasSelectionSubTools && section.toolbarGroup?.subToolId !== activeSubToolId) return null;
                                    }
                                    return <ToolbarItem key={section.id}>{typeof section.content === "function" ? section.content() : section.content}</ToolbarItem>;
                                  })}
                                </ToolbarScopeWrapper>
                              </ToolbarZone>
                            </LevelProvider>
                          </div>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div id="semio.sketchpad.toolbar" className="hidden" />
                  )
                ) : undefined
              }
              canvas={
                <div className="relative h-full w-full">
                  <AppRouter />
                </div>
              }
            />
          </ToolbarScopeWrapper>
        </LevelProvider>
        <DragOverlay>
          {activeDragId && activeDragData ? (
            <div className="cursor-grabbing">
              <div className="border border-element rounded-full w-small h-small flex items-center justify-center shadow-lg">
                <span className="text-small font-medium select-none">{getTypeOrDesignName()?.substring(0, 2).toUpperCase() || "?"}</span>
              </div>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </TutorialProvider>
  );
};

// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨sketchpadinteractionbridge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/SketchpadInteractionBridge)
/**
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨sketchpadinteractionbridge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/SketchpadInteractionBridge)
 * SketchpadInteractionBridge holds the data fields for a SketchpadInteractionBridge record.
 **/
const SketchpadInteractionBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const sketchpadCommands = useSketchpadCommands();
  const activeInteraction = useActiveInteraction();

  const interactionCommands = useMemo(
    () => ({
      setActiveInteraction: (elementId?: string, interactionId?: string) => {
        sketchpadCommands.setActiveInteraction(elementId || "semio.interaction", interactionId);
      },
    }),
    [sketchpadCommands],
  );

  return (
    <InteractionProvider commands={interactionCommands} activeInteraction={activeInteraction}>
      {children}
    </InteractionProvider>
  );
};

// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨globalnavigationbridge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/GlobalNavigationBridge)
/**
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨globalnavigationbridge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/GlobalNavigationBridge)
 * GlobalNavigationBridge holds the data fields for a GlobalNavigationBridge record.
 **/
const GlobalNavigationBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const reactNavigate = useReactNavigate();

  useEffect(() => {
    if (typeof window !== "undefined") {
      (window as any).__SEMIO_NAVIGATE__ = reactNavigate;
    }
    return () => {
      if (typeof window !== "undefined") {
        delete (window as any).__SEMIO_NAVIGATE__;
      }
    };
  }, [reactNavigate]);

  return <>{children}</>;
};

