    if (!canSet || !kitGuid) return undefined;
    return (tool: ToolKind) => actor.send({ type: "KIT.SET_ACTIVE_TOOL", kitGuid, tool } as any);
  }, [actor, canSet, kitGuid]);

  return conditionalHookResult(canSet, activeTool, setActiveTool);
}

