        const centerY = rect.height / 2;
        reactFlowInstanceRef.current.setViewport({ x: centerX, y: centerY, zoom: 1 });
        if (setDiagramCenter) setDiagramCenter({ u: centerX / ICON_WIDTH, v: -centerY / ICON_WIDTH });
