      if (!connectionGuid) return;
      const compositionKind = resolveSelectionCompositionKind(activeToolRef.current, {
        shiftKey: e.shiftKey,
        altKey: e.altKey,
        ctrlKey: e.ctrlKey,
        metaKey: e.metaKey,
