const FormulaWindow = memo(() => <Formula />);
FormulaWindow.displayName = "FormulaWindow";

/**
 * [👤semio📚js🗃️sketchpad💻quality🔖app🪨diagramwindow](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/QualityApp/d/i/DiagramWindow)
