// #region 🔖Docs
export interface MDXModule {
  default: React.ComponentType;
  frontmatter?: PageFrontmatter;
}

/**
 * Frontmatter metadata for a docs section index page.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🛠️sectionfrontmatter](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/SectionFrontmatter)
 **/
export interface SectionFrontmatter {
  title?: string;
  description?: string;
  icon?: string;
  order?: number;
  sidebar?: {
    label?: string;
  };
}

/**
 * File info for a loaded MDX file including path, section, and frontmatter.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🛠️mdxfileinfo](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/MDXFileInfo)
 **/
export interface MDXFileInfo {
  path: string;
  section: string;
  title: string;
  description?: string;
  icon?: string;
  order?: number;
  concepts?: string[];
  module?: MDXModule;
}

/**
 * Metadata for a docs section including label, icon, and sort order.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🛠️sectioninfo](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/SectionInfo)
 **/
export interface SectionInfo {
  id: string;
  label: string;
  description?: string;
  icon?: string;
  order: number;
}

/**
 * mdxModuleLoaders holds lazy MDX module loaders keyed by page path.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🪨mdxmodules](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/mdxModules)
 **/
const mdxModuleLoaders = import.meta.glob<MDXModule>("./pages/**/*.mdx");

/**
 * mdxModulePaths holds every docs page path discovered by Vite.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🪨mdxmodulepaths](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/mdxModulePaths)
 **/
const mdxModulePaths = Object.keys(mdxModuleLoaders);

interface DocsMetadataState {
  loadingPromise: Promise<void> | null;
  pages: MDXFileInfo[] | null;
  sections: SectionInfo[] | null;
  version: number;
  listeners: Set<() => void>;
}

/**
 * docsMetadataState caches docs metadata after the first asynchronous load.
 *Root app startup MUST NOT eagerly evaluate every docs page module.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🪨docsmetadatastate](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/docsMetadataState)
 **/
const docsMetadataState: DocsMetadataState = {
  loadingPromise: null,
  pages: null,
  sections: null,
  version: 0,
  listeners: new Set(),
};

function emitDocsMetadataChanged(): void {
  docsMetadataState.version += 1;
  docsMetadataState.listeners.forEach((listener) => listener());
}

function subscribeDocsMetadata(listener: () => void): () => void {
  docsMetadataState.listeners.add(listener);
  return () => {
    docsMetadataState.listeners.delete(listener);
  };
}

function getDocsMetadataVersion(): number {
  return docsMetadataState.version;
}

function isSectionIndexFile(filePath: string): boolean {
  const parts = filePath.replace("./pages/", "").split("/");
  return parts.length === 2 && parts[1] === "index.mdx";
}

function buildMDXFiles(modules?: Record<string, MDXModule>): MDXFileInfo[] {
  return mdxModulePaths
    .filter((filePath) => {
      if (filePath === "./pages/index.mdx") return true;
      if (isSectionIndexFile(filePath)) return false;
      return true;
    })
    .map((filePath) => {
      const module = modules?.[filePath];
      const cleanPath = filePath.replace("./pages/", "").replace(".mdx", "");
      const fullPath = `docs/${cleanPath}`;
      const frontmatter = module?.frontmatter;
      return {
        path: fullPath,
        section: pathToSection(filePath),
        title: pathToTitle(filePath, frontmatter),
        description: frontmatter?.description,
        icon: frontmatter?.icon,
        order: frontmatter?.order ?? 999,
        concepts: frontmatter?.concepts,
        module,
      };
    });
}

function buildSections(modules?: Record<string, MDXModule>): SectionInfo[] {
  const sectionsMap = new Map<string, SectionInfo>();

  mdxModulePaths.forEach((filePath) => {
    const parts = filePath.replace("./pages/", "").split("/");
    if (parts.length > 1) {
      const sectionId = parts[0];
      if (!sectionsMap.has(sectionId)) {
        const indexPath = `./pages/${sectionId}/index.mdx`;
        const frontmatter = modules?.[indexPath]?.frontmatter as SectionFrontmatter | undefined;
        sectionsMap.set(sectionId, {
          id: sectionId,
          label:
            frontmatter?.sidebar?.label ||
            frontmatter?.title ||
            sectionId
              .split("-")
              .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
              .join(" "),
          description: frontmatter?.description,
          icon: frontmatter?.icon,
          order: frontmatter?.order ?? 999,
        });
      }
    }
  });

  return Array.from(sectionsMap.values()).sort((a, b) => a.order - b.order);
}

const fallbackMDXFiles = buildMDXFiles();
const fallbackSections = buildSections();

async function ensureDocsMetadataLoaded(): Promise<void> {
  if (docsMetadataState.pages && docsMetadataState.sections) {
    return;
  }

  if (docsMetadataState.loadingPromise) {
    return docsMetadataState.loadingPromise;
  }

  docsMetadataState.loadingPromise = (async () => {
    const entries = await Promise.all(
      mdxModulePaths.map(async (filePath) => {
        const module = await mdxModuleLoaders[filePath]();
        return [filePath, module] as const;
      }),
    );

    const modules = Object.fromEntries(entries) as Record<string, MDXModule>;
    docsMetadataState.pages = buildMDXFiles(modules);
    docsMetadataState.sections = buildSections(modules);
    emitDocsMetadataChanged();
  })().finally(() => {
    docsMetadataState.loadingPromise = null;
  });

  return docsMetadataState.loadingPromise;
}

function useDocsMetadataVersion(): number {
  useEffect(() => {
    void ensureDocsMetadataLoaded();
  }, []);

  return useSyncExternalStore(subscribeDocsMetadata, getDocsMetadataVersion, getDocsMetadataVersion);
}

/**
 * Loads an MDX file by path from the lazy-loaded module map.
 *The path MUST be relative to the pages directory without extension.
 * [👤semio📚js🗃️sketchpad💻docs🔖mdxloader🛠️loadmdxfile](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/loadMDXFile)
 **/
export async function loadMDXFile(path: string): Promise<MDXModule | null> {
  const cleanPath = path.replace(/^docs\//, "");
  const possibleKeys = mdxModulePaths.filter((key) => {
    const keyPath = key.replace("./pages/", "").replace(".mdx", "");
    return keyPath === cleanPath || keyPath === `${cleanPath}/index`;
  });

  if (possibleKeys.length > 0) {
    const modulePath = possibleKeys[0];
    try {
      const module = await mdxModuleLoaders[modulePath]();
      return module;
    } catch {
      return null;
    }
  }
  return null;
}

