 **/
const subscribeHeadings = (callback: () => void) => headingsState.subscribe(callback);
// [👤semio📚js🗃️sketchpad💻docs🪨getheadingssnapshot](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/d/i/getHeadingsSnapshot)
