    const current = this._kitStore.getSnapshot().kit;
    const diff: any = {};
    for (const [key, value] of Object.entries(partial)) {
      if (value !== (current as any)[key]) {
        diff[key] = value;
      }
    }
    this._kitStore.apply(diff);
  }
